import hashlib
from urllib.parse import quote

# Pamela Colman Smith / Rider-Waite-Smith, public-domain originals.
# File names verified against Wikimedia Commons' TaionWC deck category.
IMAGE_NAMES = ['Fool','Magician','High Priestess','Empress','Emperor','Hierophant',
               'Lovers','Chariot','Strength','Hermit','Wheel of Fortune','Justice',
               'Hanged Man','Death','Temperance','Devil','Tower','Star','Moon','Sun','Judgement','World']

def image_url(number):
    filename = f'RWS_Tarot_{number:02}_{IMAGE_NAMES[number].replace(" ","_")}.jpg'
    digest = hashlib.md5(filename.encode(),usedforsecurity=False).hexdigest()
    return f'https://upload.wikimedia.org/wikipedia/commons/{digest[0]}/{digest[:2]}/{quote(filename)}'

DECK = [dict(name=r[0],keyword=r[1],description=r[2],symbolism=r[3],image_url=image_url(i),
             reading_male=r[4],reading_female=r[4],action_guide=r[5],number=i)
        for i,r in enumerate(ROWS)]
